public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[left] <= nums[mid]) {
            if (target < nums[mid] && target >= nums[left]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Get the index of the 5% and 95% percentile
    int low = (int) Math.ceil(arr.length * 0.05);
    int high = (int) Math.floor(arr.length * 0.95);

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = low; i <= high; i++) {
        sum += arr[i];
    }

    // Return the average of the remaining elements
    return sum / (high - low + 1);
}

