public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    while (chars.length > 0) {
        // pick the smallest character and append it to the result
        char smallest = chars[0];
        result.append(smallest);
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        // pick the smallest character that is greater than the last appended character and append it to the result
        int smallestIndex = -1;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] > smallest) {
                smallestIndex = i;
                break;
            }
        }
        if (smallestIndex != -1) {
            result.append(chars[smallestIndex]);
            chars = Arrays.copyOfRange(chars, 0, smallestIndex) + Arrays.copyOfRange(chars, smallestIndex + 1, chars.length);
        }
        // pick the largest character and append it to the result
        char largest = chars[chars.length - 1];
        result.append(largest);
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        // pick the largest character that is smaller than the last appended character and append it to the result
        int largestIndex = -1;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] < largest) {
                largestIndex = i;
                break;
            }
        }
        if (largestIndex != -1) {
            result.append(chars[largestIndex]);
            chars = Arrays.copyOfRange(chars, 0, largestIndex) + Arrays.copyOfRange(chars, largestIndex + 1, chars.length);
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    int avg = sum / n;
    int leftSum = 0;
    for (int i = 0; i < n / 2; i++) {
        leftSum += nums[i];
    }
    if (leftSum == avg) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    int rightSum = sum - leftSum;
    return rightSum == avg;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int prev = cost[0], curr = Math.min(cost[0], cost[1]);
    for (int i = 2; i < n; i++) {
        int next = Math.min(prev + cost[i], curr + cost[i - 1]);
        prev = curr;
        curr = next;
    }
    return curr;
}

