public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dirs = new int[][] {{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] dir : dirs) {
                int len = 0;
                for (int k = 1; k <= m && k <= n; k++) {
                    int newI = i + dir[0] * k;
                    int newJ = j + dir[1] * k;
                    if (newI < 0 || newI >= m || newJ < 0 || newJ >= n || mat[newI][newJ] == 0) {
                        break;
                    }
                    len++;
                }
                maxLen = Math.max(maxLen, len);
            }
        }
    }
    return maxLen;
}

