    StringBuilder sb = new StringBuilder();
    sb.append(str.substring(0, str.length() - (3 * numSeparators)));
    for (int i = 0; i < numSeparators; i++) {
        sb.append(".");
        sb.append(str.substring(str.length() - (3 * (i + 1)), str.length() - (3 * i)));
    }
    return sb.toString();
}

public int squarePermutations(int[] A) {
    Map<Integer, List<int[]>> squareLists = new HashMap<>();
    int n = A.length;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int square = (int) Math.sqrt(A[i] * A[j]);
            if (square == (A[i] * A[j]) / square) {
                if (!squareLists.containsKey(square)) {
                    squareLists.put(square, new ArrayList<>());
                }
                squareLists.get(square).add(new int[]{A[i], A[j]});
            }
        }
    }
    int permutations = 0;
    for (List<int[]> list : squareLists.values()) {
        permutations += list.size() * (list.size() - 1) / 2;
    }
    return permutations;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftMax = new int[n];
    int[] rightMax = new int[n];
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int height = heights[i];
        if (i == 0) {
            leftMax[i] = height;
        } else {
            leftMax[i] = Math.max(height, leftMax[i - 1]);
        }
        if (i == n - 1) {
            rightMax[i] = height;
        } else {
            rightMax[i] = Math.max(height, rightMax[i + 1]);
        }
        int width = Math.min(leftMax[i], rightMax[i]);
        maxArea = Math.max(maxArea, height * width);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];

    int i = 0, j = 0, k = 0;
    while (i < m && j < n) {
        result[k++] = mat[i][j];
        if (i == j || i + j == m - 1 || i + j == n - 1) {
            i++;
            j++;
        } else if (i < j) {
            i++;
        } else {
            j++;
        }
    }

    return result;
}

