public static int findNthUglyNumber(int n) {
    int[] result = new int[n];
    int i2 = 0, i3 = 0, i5 = 0;
    result[0] = 1;
    for (int i = 1; i < n; i++) {
        int n2 = result[i2] * 2, n3 = result[i3] * 3, n5 = result[i5] * 5;
        result[i] = Math.min(n2, Math.min(n3, n5));
        if (result[i] == n2) i2++;
        if (result[i] == n3) i3++;
        if (result[i] == n5) i5++;
    }
    return result[n - 1];
}

