}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i *= 10) {
        int digit = i % 10;
        int upper = i * 10 - 1;
        for (int j = upper; j >= i && j <= n; j /= 10) {
            if (j % 10 == digit) {
                result.add(j);
            }
        }
    }
    return result;
}

